function showAdPrompt(description, ticketCost, onComplete, placementId, subtype)
{
    hideTooltip();
    var buttons = [];
    buttons.push({
        text: _("Watch an ad"),
        icon: adButtonSmall,
        color: "blue",
        onClick: adManager.showAd.bind(adManager, onComplete, placementId)
    });
    var payText = _("Pay {0} tickets", ticketCost);
    if(ticketCost == 1)
    {
        payText = _("Pay 1 ticket");
    }
    buttons.push({
        text: payText,
        icon: smallShopTicketGold,
        color: "green",
        onClick: function ()
        {
            if(tickets >= ticketCost)
            {
                var subtypeToUse = subtype !== undefined ? subtype : IngamePurchaseSubcategories.AD_PROMPT_SKIP;
                subtractTickets(ticketCost, ShopCategories.INGAME_PURCHASE, subtypeToUse);
                onComplete();
            }
            else
            {
                showConfirmationPrompt(
                    _("You don't have enough tickets"),
                    _("BUY TICKETS"),
                    function ()
                    {
                        openUi(PurchaseWindow, null, 0, purchaseWindowTabOrder);
                        hideSimpleInput();
                    },
                    _("Cancel"));
            }
        }
    });
    buttons.push({
        text: _("Cancel"),
        color: "red",
        scale: .75,
        onClick: () => { }
    });

    showChoicePrompt(description, "", buttons);
}

