class WorldResource {
    //Static
    index;
    name;
    sellValue;
    isIsotope;
    isotopeIndex;
    indexOfWorldEncountered;
    isOnHeader = true;
    smallIcon;
    smallIconHidden;
    largeIcon;
    largeIconHidden;
    isTradable;
    countsTowardsCapacityAndValue = false;
    resetsWithAscension = true;


    //Dynamic
    numOwned = 0;
    level = 0;
    totalOwnedEver = {
        total: 0,
    };

    totalValue() {
        return this.sellValue.multiply(this.numOwned);
    }

    add(amount, source) {
        if (this.totalOwnedEver[source] == undefined) {
            this.totalOwnedEver[source] = 0;
        }

        this.totalOwnedEver[source] += amount;
        this.totalOwnedEver.total += amount;
        this.numOwned += amount;
    }
}

