function getPremiumMinerName(minerDepth, minerIndex) {
	if (minerDepth >= paidMinerNames[0].depth) {
		for (var i = 0; i < paidMinerNames.length; i++) {
			if (paidMinerNames[i].depth == minerDepth && paidMinerNames[i].workerIndex == minerIndex) {
				return paidMinerNames[i].name;
			}
		}
	}
	return null;
}

function getMinerName(minerDepth, minerIndex) {
	var premiumName = getPremiumMinerName(minerDepth, minerIndex);
	if (premiumName != null) {
		return premiumName;
	}

	var nameIndex = (minerIndex + (minerDepth * 10)) % minerNames.length;
	return minerNames[nameIndex];
}

