loadSaves();
function loadSaves()
{
    if(localStorage["R"] !== undefined)
    {
        sids = localStorage["R"].split("|");
        saves = [];
        var validSaveNames = "";
        var validSaveCount = 0;

        // Check each save for validity and only keep valid saves
        for(var i = 0; i < sids.length; i++)
        {
            if(sids[i] != "")
            {
                if(isValidSave(sids[i]))
                {
                    // Valid save - keep it
                    saves[validSaveCount] = b64_to_utf8(b64_to_utf8(localStorage[sids[i]])).split("|");
                    validSaveNames += sids[i] + "|";
                    validSaveCount++;
                }
                else
                {
                    // Invalid save - don't include in the list
                    console.log("Removing invalid save: " + sids[i]);
                }
            }
        }

        // Update registry with only valid saves
        if(validSaveNames !== localStorage["R"])
        {
            localStorage["R"] = validSaveNames;
            console.log("Updated save registry to remove invalid saves");
        }

        RS = localStorage["R"] !== undefined ? localStorage["R"] : "0";
        RSc = localStorage["R"] !== undefined ? localStorage["R"].split("|").length - 1 : "0";
        if(RSc > 3) {RSc = 3;}

        // Re-initialize sids after cleanup
        sids = localStorage["R"].split("|");
    }
    else
    {
        sids = [];
        RS = "0";
        RSc = "0";
        saves = [];
    }
}


