function isValidSave(saveName)
{
    // Check if the save exists in localStorage
    if(localStorage.getItem(saveName) === null || localStorage.getItem(saveName) === "")
    {
        return false;
    }

    try
    {
        // Try to decode and validate the save data
        var saveData = localStorage[saveName];
        if(b64_to_utf8(saveData).length == 0)
        {
            return false;
        }

        var decodedData = b64_to_utf8(b64_to_utf8(saveData)).split("|");
        var versionInSave = decodedData[9];

        // Check if the version is a valid number
        if(isNaN(versionInSave))
        {
            return false;
        }

        // Ensure the save has enough data fields
        if(decodedData.length < 10)
        {
            return false;
        }

        return true;
    } catch(e)
    {
        console.error("Error validating save: " + e);
        return false;
    }
}

